  INSERT INTO public.pl_templates (
    id, name, template_type, training_style, training_focus,
    tags, status, weeks, days_per_week, est_duration_min,
    goal, notes, payload, archived
  ) VALUES (
    gen_random_uuid(),
    'Full Body Foundation — Beginner • 3-Day • Full Body Bodybuilding',
    'block',
    'bodybuilding',
    'Beginner',
    ARRAY['full-body','3-day','bodybuilding','full body']::text[],
    'Published',
    12, 3, 60,
    '3-block 12-week full-body bodybuilding program. Accumulation → Overload → Intensification.',
    '3-Day Full Body Bodybuilding. Block 1 (Wks 1-4) Accumulation 3x8-12, Block 2 (Wks 5-8) Overload 4x6-10, Block 3 (Wks 9-12) Intensification 4x4-8. RPE/RIR prescribed per week.',
    v_payload,
    false
  ) RETURNING id INTO v_id;

  INSERT INTO public.pl_template_shares (template_id, destination, status, shared_at)
  VALUES (v_id, 'membership', 'shared', now())
  ON CONFLICT (template_id, destination) DO NOTHING;

  -- Machine Muscle Builder — Beginner • 3-Day • Full Body Bodybuilding
  DELETE FROM public.pl_templates WHERE
    (name = 'Machine Muscle Builder — Beginner • 3-Day • Full Body Bodybuilding'
    OR (tags @> ARRAY['bodybuilding','full-body','3-day']::text[]
        AND training_focus = 'Beginner'
        AND days_per_week = 3
