  -- Balanced Hypertrophy — Intermediate • 3-Day • Full Body Bodybuilding
  DELETE FROM public.pl_templates WHERE
    (name = 'Balanced Hypertrophy — Intermediate • 3-Day • Full Body Bodybuilding'
    OR (tags @> ARRAY['bodybuilding','full-body','3-day']::text[]
        AND training_focus = 'Intermediate'
        AND days_per_week = 3
        AND weeks = 12
        AND name LIKE 'Balanced%'));

