  DELETE FROM public.pl_templates WHERE
    (name = 'Upper-Body Specialization — Advanced • 3-Day • Full Body Bodybuilding'
    OR (tags @> ARRAY['bodybuilding','full-body','3-day']::text[]
        AND training_focus = 'Advanced'
        AND days_per_week = 3
        AND weeks = 12
        AND name LIKE 'Upper-Body%'));

