    goal, notes, payload, archived
  ) VALUES (
    gen_random_uuid(),
    'Delts and Arms Specialization — Advanced–Elite • 3-Day • Full Body Bodybuilding',
    'block',
    'bodybuilding',
    'Advanced-Elite',
    ARRAY['full-body','3-day','bodybuilding','full body']::text[],
    'Published',
    12, 3, 60,
    '3-block 12-week full-body bodybuilding program. Accumulation → Overload → Intensification.',
    '3-Day Full Body Bodybuilding. Block 1 (Wks 1-4) Accumulation 3x8-12, Block 2 (Wks 5-8) Overload 4x6-10, Block 3 (Wks 9-12) Intensification 4x4-8. RPE/RIR prescribed per week.',
    v_payload,
    false
  ) RETURNING id INTO v_id;

