  INSERT INTO public.pl_templates (
    id, name, template_type, training_style, training_focus,
    tags, status, weeks, days_per_week, est_duration_min,
    goal, notes, payload, archived
  ) VALUES (
    gen_random_uuid(),
    'Powerbuilding Bodybuilder — Advanced–Elite • 3-Day • Full Body Powerbuilding',
    'block',
    'powerbuilding',
    'Advanced-Elite',
    ARRAY['full-body','3-day','powerbuilding','full body']::text[],
    'Published',
    12, 3, 60,
    '3-block 12-week full-body powerbuilding program. Accumulation → Overload → Intensification.',
    '3-Day Full Body Powerbuilding. Block 1 (Wks 1-4) Accumulation 3x8-12, Block 2 (Wks 5-8) Overload 4x6-10, Block 3 (Wks 9-12) Intensification 4x4-8. RPE/RIR prescribed per week.',
    v_payload,
    false
  ) RETURNING id INTO v_id;

  INSERT INTO public.pl_template_shares (template_id, destination, status, shared_at)
  VALUES (v_id, 'membership', 'shared', now())
  ON CONFLICT (template_id, destination) DO NOTHING;

  -- Autoregulated Complete Physique — Advanced–Elite • 3-Day • Full Body Bodybuilding
  DELETE FROM public.pl_templates WHERE
    (name = 'Autoregulated Complete Physique — Advanced–Elite • 3-Day • Full Body Bodybuilding'
    OR (tags @> ARRAY['bodybuilding','full-body','3-day']::text[]
        AND training_focus = 'Advanced-Elite'
        AND days_per_week = 3
        AND weeks = 12
        AND name LIKE 'Autoregulated%'));

